SourceCode.Declaration:
public class METCustomerMDFPosting_FreeTextInvoice extends METCustomerMDFPosting
{
    METConsolidationMethodEDT consolidationMethod;

}

Method.Source:
public METConsolidationMethodEDT parmConsolidationMethod(METConsolidationMethodEDT _consolidationMethod = consolidationMethod)
{
    consolidationMethod = _consolidationMethod;

    return consolidationMethod;
}

Query updateQuery(Query _query)
{
    Query ret = super(_query);

    ret.dataSourceTable(tableNum(METCustomerMDFCalculationTrans)).addRange(fieldNum(METCustomerMDFConsolidationTable, ConsolidationMethod)).value(queryValue(consolidationMethod));

    return ret;
}

void post(Common _common)
{
    CustInvoiceTable custInvoiceTable = _common as CustInvoiceTable;
}

void createFreeTextInvoiceLines(METCustomerMDFConsolidationTable _consolidationPosting)
{
    switch(_consolidationPosting.ConsolidationMethod)
    {
        case METConsolidationMethodEDT::Daily:
            this.createFreeTextInvoiceLinesDaily(_consolidationPosting);
            break;
        case METConsolidationMethodEDT::Shipment:
            this.createFreeTextInvoiceLinesShipment(_consolidationPosting);
            break;
    }
}

void createFreeTextInvoiceLinesDaily(METCustomerMDFConsolidationTable _consolidationPosting)
{
    METCustomerMDFConsolidationTable consolidationTable;

    while select forupdate consolidationTable
        where consolidationTable.CustAccount == _consolidationPosting.CustAccount
        && consolidationTable.ConsolidationMethod == METConsolidationMethodEDT::Daily
        && consolidationTable.ApplicationMethod == METApplicationMethodEDT::FreeTextInvoice
        && consolidationTable.ShipDate == _consolidationPosting.ShipDate
    {
        // Logic to create free text invoice lines for daily consolidation
        this.processConsolidationTable(consolidationTable);
    }
}

RecId createFreeTextInvoiceLine(METCustomerMDFConsolidationTable _consolidationTable)
{
    RecId freeTextInvoiceLineRecId;
    // Logic to create free text invoice line and return its RecId
    return freeTextInvoiceLineRecId;
}

void createFreeTextInvoiceLinesShipment(METCustomerMDFConsolidationTable _consolidationPosting)
{
    METCustomerMDFConsolidationTable consolidationTable;

    while select forupdate consolidationTable
        where consolidationTable.CustAccount == _consolidationPosting.CustAccount
        && consolidationTable.ConsolidationMethod == METConsolidationMethodEDT::Shipment
        && consolidationTable.ApplicationMethod == METApplicationMethodEDT::FreeTextInvoice
        && consolidationTable.ShipmentId == _consolidationPosting.ShipmentId
    {
        // Logic to create free text invoice lines for daily consolidation
        this.processConsolidationTable(consolidationTable);
    }
}
